Contract AutomatedTellerMachineSystem::ejectCard(): Boolean {
          definition:
          isCardValid: Boolean = Card.allInstance()->exists(o | o.CardID = InputCard.CardID and o.Password = InputCard.Password); isWithdrawCompleted: Boolean = not IsWithdraw and not IsDeposit; withdrewNumber: Real = 0;

            precondition:
          Card.allInstance()->includes(InputCard) and isCardValid and ob.oclIsUndefined() and InputCard.CardStatus = CardStatus.NORMAL

            postcondition:
          In the post condition, let ob:BankCard in ob.oclIsNew(); Card.allInstance()->includes(ob); ob.Balance = ob.Balance - withdrewNumber; IsWithdraw = true; IsDeposit = false; WithdrawedNumber = withdrewNumber; result = isCardValid and isWithdrawCompleted;

        }
